def pasar_datos_al_modelo_nuevo(apps, schema_editor):
    """Lleva a la factura lo que antes vivía en cada línea de venta y revisa que
    las cuentas por cobrar cumplan la nueva regla de una cuenta por factura."""
    Factura = apps.get_model("finanzas", "Factura")
    DetalleVenta = apps.get_model("finanzas", "DetalleVenta")
    CuentaPorCobrar = apps.get_model("finanzas", "CuentaPorCobrar")

    # Si alguna línea estaba ANULADA, ahora se anula la factura completa.
    anuladas = DetalleVenta.objects.filter(estado_pago="ANULADO").values("factura_id")
    Factura.objects.filter(pk__in=anuladas).update(anulada=True)

    sin_factura = CuentaPorCobrar.objects.filter(factura__isnull=True).count()
    repetidas = (
        CuentaPorCobrar.objects.values("factura_id")
        .annotate(n=models.Count("pk"))
        .filter(n__gt=1)
        .count()
    )
    if sin_factura or repetidas:
        raise RuntimeError(
            f"Hay {sin_factura} cuentas por cobrar sin factura y {repetidas} facturas con más "
            "de una cuenta. Ahora cada venta a crédito tiene una sola cuenta. Borra la base "
            "(o usa 'python manage.py importar_csv --limpiar' después de migrar con una base "
            "nueva) y vuelve a importar."
        )


